#include "SimilarityLearning.h"
#include <cmath>
#include <set>
#include <algorithm>
namespace {
void check(bool ok){if(!ok)throw std::runtime_error("Could not access local similarity feedback");}
struct Query{sqlite3_stmt* p=nullptr;Query(sqlite3* db,const char* sql){check(sqlite3_prepare_v2(db,sql,-1,&p,nullptr)==SQLITE_OK);}~Query(){sqlite3_finalize(p);}void text(int i,const juce::String& s){sqlite3_bind_text(p,i,s.toRawUTF8(),-1,SQLITE_TRANSIENT);}};
juce::String string(sqlite3_stmt* p,int column){auto* s=(const char*)sqlite3_column_text(p,column);return s?juce::String::fromUTF8(s):juce::String();}
}
SimilarityLearning::SimilarityLearning(juce::File root){root.createDirectory();check(sqlite3_open(root.getChildFile("similarity-feedback.db").getFullPathName().toRawUTF8(),&db)==SQLITE_OK);sqlite3_busy_timeout(db,1000);check(sqlite3_exec(db,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS feedback(reference TEXT,result TEXT,profile TEXT,label INTEGER,refTime INTEGER,refSize INTEGER,resultTime INTEGER,resultSize INTEGER,neural REAL,dynamics REAL,refEmbedding BLOB,resultEmbedding BLOB,refDynamics BLOB,resultDynamics BLOB,valid INTEGER,updated INTEGER,PRIMARY KEY(reference,result,profile));CREATE TABLE IF NOT EXISTS models(profile TEXT PRIMARY KEY,weight REAL,previous REAL,enabled INTEGER,details TEXT);CREATE TABLE IF NOT EXISTS training(profile TEXT,created INTEGER,details TEXT);",nullptr,nullptr,nullptr)==SQLITE_OK);}
SimilarityLearning::~SimilarityLearning(){if(db)sqlite3_close(db);}
void SimilarityLearning::save(const Example& x){
 struct Transaction{sqlite3* db;bool active;Transaction(sqlite3* handle,bool on):db(handle),active(on){if(active)check(sqlite3_exec(db,"BEGIN IMMEDIATE",nullptr,nullptr,nullptr)==SQLITE_OK);}void commit(){if(active){check(sqlite3_exec(db,"COMMIT",nullptr,nullptr,nullptr)==SQLITE_OK);active=false;}}~Transaction(){if(active)sqlite3_exec(db,"ROLLBACK",nullptr,nullptr,nullptr);}} transaction(db,x.label==2);
 if(x.label==2){Query old(db,"UPDATE feedback SET label=1 WHERE reference=? AND profile=? AND label=2 AND result<>?");old.text(1,x.reference);old.text(2,x.profile);old.text(3,x.result);check(sqlite3_step(old.p)==SQLITE_DONE);}
if(!x.label){Query q(db,"DELETE FROM feedback WHERE reference=? AND result=? AND profile=?");q.text(1,x.reference);q.text(2,x.result);q.text(3,x.profile);check(sqlite3_step(q.p)==SQLITE_DONE);return;}Query q(db,"INSERT OR REPLACE INTO feedback VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");q.text(1,x.reference);q.text(2,x.result);q.text(3,x.profile);sqlite3_bind_int(q.p,4,x.label);for(auto item:{std::pair<int,int64_t>{5,x.refTime},{6,x.refSize},{7,x.resultTime},{8,x.resultSize}})sqlite3_bind_int64(q.p,item.first,item.second);sqlite3_bind_double(q.p,9,x.neural);sqlite3_bind_double(q.p,10,x.dynamics);sqlite3_bind_blob(q.p,11,x.refEmbedding.data(),sizeof(x.refEmbedding),SQLITE_TRANSIENT);sqlite3_bind_blob(q.p,12,x.resultEmbedding.data(),sizeof(x.resultEmbedding),SQLITE_TRANSIENT);sqlite3_bind_blob(q.p,13,x.refDynamics.data(),sizeof(x.refDynamics),SQLITE_TRANSIENT);sqlite3_bind_blob(q.p,14,x.resultDynamics.data(),sizeof(x.resultDynamics),SQLITE_TRANSIENT);sqlite3_bind_int(q.p,15,x.valid);sqlite3_bind_int64(q.p,16,juce::Time::currentTimeMillis());check(sqlite3_step(q.p)==SQLITE_DONE);transaction.commit();}
std::map<juce::String,int> SimilarityLearning::labels(const juce::String& reference,const juce::String& profile){Query q(db,"SELECT result,label,resultTime,resultSize,refTime,refSize FROM feedback WHERE reference=? AND profile=?");q.text(1,reference);q.text(2,profile);std::map<juce::String,int> out;while(sqlite3_step(q.p)==SQLITE_ROW){juce::File ref(reference),file(string(q.p,0));if(ref.existsAsFile()&&file.existsAsFile()&&ref.getLastModificationTime().toMilliseconds()==sqlite3_column_int64(q.p,4)&&ref.getSize()==sqlite3_column_int64(q.p,5)&&file.getLastModificationTime().toMilliseconds()==sqlite3_column_int64(q.p,2)&&file.getSize()==sqlite3_column_int64(q.p,3))out[file.getFullPathName()]=sqlite3_column_int(q.p,1);}return out;}
SimilarityLearning::Summary SimilarityLearning::summary(const juce::String& profile){Summary s;Query q(db,"SELECT sum(label>0),sum(label=-1),count(DISTINCT reference) FROM feedback WHERE profile=? AND valid=1");q.text(1,profile);if(sqlite3_step(q.p)==SQLITE_ROW){s.positive=sqlite3_column_int(q.p,0);s.negative=sqlite3_column_int(q.p,1);s.references=sqlite3_column_int(q.p,2);}Query m(db,"SELECT weight,previous,enabled FROM models WHERE profile=?");m.text(1,profile);if(sqlite3_step(m.p)==SQLITE_ROW){s.model=true;s.weight=sqlite3_column_double(m.p,0);s.previous=sqlite3_column_double(m.p,1);s.enabled=sqlite3_column_int(m.p,2)!=0;}return s;}
std::vector<SimilarityLearning::Example> SimilarityLearning::examples(const juce::String& profile){Query q(db,"SELECT reference,result,profile,label,refTime,refSize,resultTime,resultSize,neural,dynamics,refEmbedding,resultEmbedding,refDynamics,resultDynamics,valid FROM feedback WHERE profile=? ORDER BY reference,result");q.text(1,profile);std::vector<Example> out;while(sqlite3_step(q.p)==SQLITE_ROW){Example x;x.reference=string(q.p,0);x.result=string(q.p,1);x.profile=string(q.p,2);x.label=sqlite3_column_int(q.p,3);x.refTime=sqlite3_column_int64(q.p,4);x.refSize=sqlite3_column_int64(q.p,5);x.resultTime=sqlite3_column_int64(q.p,6);x.resultSize=sqlite3_column_int64(q.p,7);x.neural=sqlite3_column_double(q.p,8);x.dynamics=sqlite3_column_double(q.p,9);if(!std::isfinite(x.neural)||!std::isfinite(x.dynamics))continue;auto blob=[&](int i,auto& a){if(sqlite3_column_bytes(q.p,i)!=(int)sizeof(a))return false;std::memcpy(a.data(),sqlite3_column_blob(q.p,i),sizeof(a));return true;};bool readable=blob(10,x.refEmbedding)&&blob(11,x.resultEmbedding)&&blob(12,x.refDynamics)&&blob(13,x.resultDynamics);x.valid=readable&&sqlite3_column_int(q.p,14)!=0;if(readable)out.push_back(x);}return out;}
SimilarityLearning::Training SimilarityLearning::train(const juce::String& profile,double baseline,std::function<bool()> cancelled){Training result;auto summaryValue=summary(profile);if(!summaryValue.trainable()){result.message="Collect at least 20 ratings (5 similar, 5 not similar) across 3 references in this search mode.";return result;}auto rows=examples(profile);rows.erase(std::remove_if(rows.begin(),rows.end(),[](const auto& x){return !x.valid;}),rows.end());std::vector<juce::String> references;for(auto& x:rows)if(std::find(references.begin(),references.end(),x.reference)==references.end())references.push_back(x.reference);std::sort(references.begin(),references.end(),[](auto a,auto b){return (uint64_t)a.hashCode64()<(uint64_t)b.hashCode64();});std::set<juce::String> held;for(auto& reference:references)if((uint64_t)reference.hashCode64()%3==0)held.insert(reference);
 auto quality=[&](double weight,bool validation){double good=0,count=0;struct Group{std::vector<double> positive,negative,best,ordinary;};std::map<juce::String,Group> grouped;for(auto& x:rows){if(cancelled())return -1.;if(held.count(x.reference)!=(size_t)validation)continue;auto& group=grouped[x.reference];double score=weight*x.neural+(1-weight)*x.dynamics;if(x.label>0)group.positive.push_back(score);else group.negative.push_back(score);if(x.label==2)group.best.push_back(score);else if(x.label==1)group.ordinary.push_back(score);}auto compare=[&](const auto& preferred,auto& other,double strength){std::sort(other.begin(),other.end());for(double score:preferred){if(cancelled())return false;auto lower=std::lower_bound(other.begin(),other.end(),score),upper=std::upper_bound(other.begin(),other.end(),score);good+=strength*(other.end()-upper+.5*(upper-lower));count+=strength*other.size();}return true;};for(auto& entry:grouped){auto& group=entry.second;if(!compare(group.positive,group.negative,1)||!compare(group.best,group.ordinary,2))return -1.;}return count>=3?good/count:-1.;};


 double current=summaryValue.model&&summaryValue.enabled?summaryValue.weight:baseline;double best=current,bestScore=quality(current,false);if(bestScore<0){result.message="Rate both similar and dissimilar matches on more references so training and validation can be separated.";return result;}for(double w:{.05,.1,.2,.35,.5,.65,.8,.9,.95}){double score=quality(w,false);if(cancelled()){result.message="Learning cancelled; previous ranking kept.";return result;}if(score>bestScore+1e-8){best=w;bestScore=score;}}result.weight=best;result.baseline=quality(current,true);result.validation=quality(best,true);if(cancelled()){result.message="Learning cancelled; previous ranking kept.";return result;}result.accepted=result.baseline>=0&&result.validation>result.baseline+.01;if(result.accepted){Query q(db,"INSERT OR REPLACE INTO models VALUES(?,?,?,1,?)");q.text(1,profile);sqlite3_bind_double(q.p,2,best);sqlite3_bind_double(q.p,3,current);q.text(4,"Validated on reference sounds excluded from training");check(sqlite3_step(q.p)==SQLITE_DONE);result.message="Personal ranking improved on held-out references. Use personal ranking is now on.";}else result.message="New ranking did not improve held-out results; your previous ranking was kept.";Query log(db,"INSERT INTO training VALUES(?,?,?)");log.text(1,profile);sqlite3_bind_int64(log.p,2,juce::Time::currentTimeMillis());log.text(3,result.message+"; previous="+juce::String(result.baseline)+"; candidate="+juce::String(result.validation));check(sqlite3_step(log.p)==SQLITE_DONE);return result;}
void SimilarityLearning::enable(const juce::String& profile,bool on){Query q(db,"UPDATE models SET enabled=? WHERE profile=?");sqlite3_bind_int(q.p,1,on);q.text(2,profile);check(sqlite3_step(q.p)==SQLITE_DONE);}
void SimilarityLearning::revert(const juce::String& profile){Query q(db,"UPDATE models SET weight=previous,previous=weight,enabled=1 WHERE profile=?");q.text(1,profile);check(sqlite3_step(q.p)==SQLITE_DONE);}
bool SimilarityLearning::exportTo(juce::File file,std::function<bool()> cancelled){juce::TemporaryFile temporary(file);juce::FileOutputStream out(temporary.getFile());if(!out.openedOk())return false;out<<"{\"format\":\"SliceGroupsSimilarityFeedback-v2\",\"audioIncluded\":false,\"featureModel\":\"clap-unfused-8fa0f1c6\",\"ratings\":[";Query q(db,"SELECT DISTINCT profile FROM feedback ORDER BY profile");bool first=true;while(sqlite3_step(q.p)==SQLITE_ROW)for(auto& x:examples(string(q.p,0))){if(cancelled())return false;juce::var v(new juce::DynamicObject());auto* o=v.getDynamicObject();o->setProperty("reference",x.reference);o->setProperty("result",x.result);o->setProperty("mode",x.profile);o->setProperty("label",x.label);o->setProperty("rating",x.label==2?"best match":x.label>0?"similar":"not similar");o->setProperty("validForLearning",x.valid);o->setProperty("referenceModified",x.refTime);o->setProperty("referenceBytes",x.refSize);o->setProperty("resultModified",x.resultTime);o->setProperty("resultBytes",x.resultSize);o->setProperty("soundDistance",x.neural);o->setProperty("dynamicsDistance",x.dynamics);auto add=[&](const char* key,const auto& values){juce::Array<juce::var> a;for(auto v:values)a.add(v);o->setProperty(key,a);};add("referenceEmbedding",x.refEmbedding);add("resultEmbedding",x.resultEmbedding);add("referenceDynamics",x.refDynamics);add("resultDynamics",x.resultDynamics);if(!first)out<<",";first=false;out<<juce::JSON::toString(v,true);}out<<"]}";out.flush();return !out.getStatus().failed()&&!cancelled()&&temporary.overwriteTargetFileWithTemporary();}
